{
  "ok": true,
  "tool": "list_operations",
  "operations": [
    {
      "op": "add_title_block",
      "category": "annotate",
      "description": "Insert the standard 180x32 mm title block (ISO-like) with attributes ['TITLE', 'DWG_NO', 'MATERIAL', 'SCALE', 'UNITS', 'DRAWN_BY', 'DATE', 'SHEET']. 'insert' is the lower-right corner (usually the inner border corner).",
      "params": {
        "type": "object",
        "properties": {
          "insert": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": " [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "fields": {
            "type": "object",
            "description": "Attribute values, e.g. {TITLE: 'Plate'}"
          },
          "size_factor": {
            "type": "number",
            "description": "Scale relative to the mm size",
            "exclusiveMinimum": 0,
            "default": 1.0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "insert"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_table",
      "category": "annotate",
      "description": "Simple table drawn as grid lines + TEXT. 'insert' is the top-left corner. Cell texts get tags '<tag>.r<row>c<col>' when 'tag' is given.",
      "params": {
        "type": "object",
        "properties": {
          "insert": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": " [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "rows": {
            "type": "array",
            "description": "List of rows, each a list of cell strings"
          },
          "col_widths": {
            "type": "array",
            "description": "Column widths"
          },
          "row_height": {
            "type": [
              "number",
              "string"
            ],
            "description": " (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0,
            "default": 8.0
          },
          "text_height": {
            "type": [
              "number",
              "string"
            ],
            "description": " (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0,
            "default": 2.5
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "insert",
          "rows",
          "col_widths"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_rectangle",
      "category": "draw",
      "description": "Draw an axis-aligned (optionally rotated) rectangle as a closed polyline. Give either 'corner' (lower-left) or 'center'.",
      "params": {
        "type": "object",
        "properties": {
          "corner": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Lower-left corner [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Center point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "width": {
            "type": [
              "number",
              "string"
            ],
            "description": "Size along X (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "height": {
            "type": [
              "number",
              "string"
            ],
            "description": "Size along Y (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "corner_radius": {
            "type": [
              "number",
              "string"
            ],
            "description": "Fillet radius of all four corners (drawing units, or string with unit e.g. '8mm')",
            "minimum": 0,
            "default": 0.0
          },
          "rotation": {
            "type": "number",
            "description": "Rotation about the corner/center (degrees, counter-clockwise)",
            "default": 0.0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "width",
          "height"
        ],
        "additionalProperties": false
      }
    }
  ],
  "count": 3,
  "detail": true,
  "constraint_types": {
    "check": [
      "angle",
      "coincident",
      "concentric",
      "diameter",
      "distance",
      "equal",
      "fixed",
      "horizontal",
      "length",
      "parallel",
      "perpendicular",
      "radius",
      "symmetric",
      "tangent",
      "vertical"
    ],
    "enforce": [
      "coincident",
      "concentric",
      "diameter",
      "distance",
      "equal",
      "fixed",
      "horizontal",
      "length",
      "parallel",
      "perpendicular",
      "radius",
      "vertical"
    ]
  },
  "metrics": {
    "duration_ms": 0.15,
    "input_bytes": 70,
    "output_bytes": 6431
  }
}

